class Animal:
    def make_sound(self): print("Animal sound")
class Dog(Animal):
    def make_sound(self):
        print("Bark!")
class Cat(Animal):
    def make_sound(self):
        print("Meow ! ")

pet_name = "Moti"
class Animal:
    def __init__(self, name):
        self.name = name
    def introduce(self):
        print("My name is", self.name)
    def make_sound(self):
        print("Animal sound")
class Dog(Animal):
    def make_sound(self):
        print("Bark!")
pet = Dog(pet_name)
pet.introduce()     # Animal se inherit hua method
pet.make_sound()    # Dog ka apna method
